nextflow_process {

    name "Test Process GALAH"
    script "../main.nf"
    config "./nextflow.config"
    process "GALAH"

    tag "modules"
    tag "modules_nfcore"
    tag "galah"
    tag "untar"
    tag "checkm2/predict"
    tag "gawk"

    test("genomes - no qc_table") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [file("https://github.com/nf-core/test-datasets/raw/refs/heads/magmap/testdata/GCA_002688505.1_ASM268850v1_genomic.fna.gz", checkIfExists: true),
                    file("https://github.com/nf-core/test-datasets/raw/refs/heads/magmap/testdata/GCF_004296495.1_ASM429649v1_genomic.fna.gz", checkIfExists: true)],
                    [],
                    []
                    ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match()
                }
            )
        }

    }

    test("genomes - checkm2 qc_table") {

        setup {

            run("GAWK") {
                script "../../gawk/main.nf"
                process {
                    """
                    input[0] = [[id: 'test'], file(params.modules_testdata_base_path + "delete_me/galah/checkm2_report.tsv", checkIfExists: true), ""]
                    input[1] = []
                    input[2] = false
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                    [file("https://github.com/nf-core/test-datasets/raw/refs/heads/magmap/testdata/GCA_002688505.1_ASM268850v1_genomic.fna.gz", checkIfExists: true),
                    file("https://github.com/nf-core/test-datasets/raw/refs/heads/magmap/testdata/GCF_004296495.1_ASM429649v1_genomic.fna.gz", checkIfExists: true)]
                ])
                .combine(GAWK.out.output, by: 0)
                // rename 'test' to 'input' to avoid name collision
                .map { meta, bins, tsv -> [ meta + [id: "input"], bins, tsv, "checkm2" ] }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match()
                }
            )
        }

    }

    test("genomes - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [file("https://github.com/nf-core/test-datasets/raw/refs/heads/magmap/testdata/GCA_002688505.1_ASM268850v1_genomic.fna.gz", checkIfExists: true),
                    file("https://github.com/nf-core/test-datasets/raw/refs/heads/magmap/testdata/GCF_004296495.1_ASM429649v1_genomic.fna.gz", checkIfExists: true)],
                    [],
                    "checkm2"
                    ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match()
                }
            )
        }

    }

}

process {
    withName: 'CHECKM2_PREDICT' {
        ext.args = "--extension gz --lowmem"
    }
    withName: 'GAWK' {
        ext.args2 = "'BEGIN {FS = OFS = \"\\t\"} NR == 1 {print \$0} NR > 1 {\$1=\$1\".fna\"; print \$0}'"
    }
}
